//★Wcraft guide★ include부분 주석처리 -> include("../js/calendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
// 상장관련공통함수
//★Wcraft guide★ include부분 주석처리 -> include("../js/stockSearch.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils_detect.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/json2.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/report.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징


scwin.vScrenID = "ULDSTF35404.xml";
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    var urldep = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD.DataID = encodeURI(urldep);
    dts_DEP_CD.Reset();
    var urlemp = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO.DataID = encodeURI(urlemp);
    dts_EMP_NO.Reset();
    $c.stf.setObjectValue(cmb_DEP_CD, '');
    $c.stf.setObjectValue(cmb_EMP_NO, '');

    /*
    		dts_DepCd.DataID = "/AdminAndDlstedDetection.do?method=getComboList&For=DR_K&outputMessageId=AADD_OUT_COMBO";	
    		dts_DepCd.Reset();

    		dts_EmpNo.DataID = "/AdminAndDlstedDetection.do?method=getComboList&For=ER_K&outputMessageId=AADD_OUT_COMBO";
    		dts_EmpNo.Reset();	*/

};



// 종류주식 주주수요건 검색 
scwin.fn_list_sync = function() {
    var isu_cd = txb_ISUR_CD.getValue();
    var team_cd = $c.cp.valueOfIndex(cmb_DEP_CD, "VALUE", cmb_DEP_CD.getSelectedIndex());
    var charge_id = $c.cp.valueOfIndex(cmb_EMP_NO, "VALUE", cmb_EMP_NO.getSelectedIndex());
    var url = "/AdminAndDlstedDetection.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=getStockList&For=KOSKCD&inputMessageId=AADD_IN&outputMessageId=AADD_OUT_KOSKCD&ISU_CD=" + isu_cd + "&TEAM_CD=" + team_cd + "&CHARGE_ID=" + charge_id;
    dts1.DataID = encodeURI(url);
    dts1.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.dts1_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.dts1_OnLoadError = function() {
    $c.stf.alert_error(dts1);
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.btn_ISUR_CD_onclick = function() {
    //IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    //  JongmokSearch(txb_ISUR_CD, txb_COM_NM, SECUGRP_ID_ST, js_market, "A");
    $c.stockSearch.JongmokSearch3(txb_ISUR_CD, txb_COM_NM, SECUGRP_ID_ST, js_market, "A");
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.dts_DEP_CD_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(cmb_DEP_CD, '');
};
scwin.dts_EMP_NO_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(cmb_EMP_NO, '');
};
scwin.cmb_DEP_CD_OnSelChange = function() {
    scwin.gDepCd = $c.stf.getObjectValue(cmb_DEP_CD);
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EMP_NO, '');
    }
    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
    dts_EMP_NO.sort("DEP_CD", 0);
    //dts_EMP_NO.sort(); // W-Craft 주석처리 

};
scwin.dts_EMP_NO_OnFilter = function(row) {
    if (scwin.gDepCd == "") {
        return true;
    } else {
        if (dts_EMP_NO.getCellData(row, "DEP_CD") == scwin.gDepCd || dts_EMP_NO.getCellData(row, "DEP_CD") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.btn_Excel_onclick = function() {
    $c.data.downloadGridViewExcel(grd_Grid, "종류주식-주식수요건", "", "8");
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.grd_Grid_OnUserColor = function(row, eventId) {
    var colorYellow = "#FFFFCC";
    var colorGreen = "#CCFFCC";
    var colorRed = "#FFCCCC";
    if (eventId == "acolor7" && (dts1.getCellData(row, "ADMISU_DESIGN_YN") == "해당")) {
        return colorYellow;
    }
    if (eventId == "acolor12" && (dts1.getCellData(row, "ADMISU_RELEAS_YN") == "해당")) {
        return colorGreen;
    }
    if (eventId == "acolor15" && (dts1.getCellData(row, "DELIST_YN") == "해당")) {
        return colorRed;
    }
    if (row % 2 == 0) return "#f2f5f9";

    else return "#ffffff";
};
scwin.gform_onload = function() {
    scwin.fn_SetCode();
    $c.cm.fn_com_isu(txb_ISUR_CD, txb_COM_NM);
    Grd_com_isur.style.zIndex = 30;
    $c.cm.PanelToGroupBox(panel_1);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
